// lookup demo — President #1: George Washington (jahdb demo program)
var DATA={"President #1: George Washington":"First president; set precedents including the two-term tradition."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("1789-1797"));

